import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
p={'db':'pubmed','term':'(PNPLA3 OR adiponutrin) AND (adipose OR adipose tissue) AND (bariatric OR surgery OR weight loss)','retmax':30,'retmode':'json'}
r=requests.get(u,params=p,timeout=20); print('status',r.status_code); ids=r.json()['esearchresult']['idlist']; print('PMIDs',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids: print(i, x[i].get('title'))
